def _check_ranges_strict(rng):
    """CONFIG ranges: sorted, disjoint, nonadjacent."""
    if type(rng) is not list:
        raise Invalid()
    if len(rng) > 32:
        raise Invalid()
    prev = None
    for pair in rng:
        if type(pair) is not list or len(pair) != 2:
            raise Invalid()
        lo = pair[0]
        hi = pair[1]
        if not _is_int(lo) or not _is_int(hi):
            raise Invalid()
        if lo < 0 or hi > MAXN or lo > hi:
            raise Invalid()
        if prev is not None and lo <= prev + 1:
            raise Invalid()
        prev = hi


def _check_ranges_loose(rng):
    """Frame ACK ranges: only endpoint/length domains are input constraints."""
    if type(rng) is not list:
        raise Invalid()
    if len(rng) > 32:
        raise Invalid()
    for pair in rng:
        if type(pair) is not list or len(pair) != 2:
            raise Invalid()
        lo = pair[0]
        hi = pair[1]
        if not _is_int(lo) or not _is_int(hi):
            raise Invalid()
        if lo < 0 or hi > MAXN:
            raise Invalid()


def _validate_frame(fr):
    """Validate one frame; return its decoded data byte count."""
    if type(fr) is not dict:
        raise Invalid()
    ty = fr.get("type")
    if type(ty) is not str:
        raise Invalid()
    keys = _FRAME_KEYS.get(ty)
    if keys is None:
        raise Invalid()
    if set(fr) != keys:
        raise Invalid()
    if ty == "ACK":
        _check_ranges_loose(fr["ranges"])
        return 0
    if ty == "CRYPTO" or ty == "STREAM":
        off = fr["offset"]
        if not _is_int(off) or off < 0 or off > MAXN:
            raise Invalid()
        n = _check_hex(fr["data_hex"])
        if ty == "STREAM":
            sid = fr["id"]
            if not _is_int(sid) or sid < 0 or sid > MAXN:
                raise Invalid()
            if not _is_bool(fr["fin"]):
                raise Invalid()
        return n
    if ty == "RESET_STREAM" or ty == "STOP_SENDING":
        sid = fr["id"]
        if not _is_int(sid) or sid < 0 or sid > MAXN:
            raise Invalid()
        if ty == "RESET_STREAM":
            fs = fr["final_size"]
            if not _is_int(fs) or fs < 0 or fs > MAXN:
                raise Invalid()
        return 0
    if ty == "CLOSE":
        if not _is_bool(fr["app"]):
            raise Invalid()
        code = fr["code"]
        if not _is_int(code) or code < 0 or code > MAXN:
            raise Invalid()
    return 0


def _validate_config(cfg):
    if type(cfg) is not dict:
        raise Invalid()
    if set(cfg) != _CFG_KEYS:
        raise Invalid()
    if not _is_bool(cfg["early"]):
        raise Invalid()
    if cfg["overlap"] not in ("reject", "first"):
        raise Invalid()
    v = cfg["buffer_packets"]
    if not _is_int(v) or v < 0 or v > 1024:
        raise Invalid()
    v = cfg["idle_ms"]
    if not _is_int(v) or v < 0 or v > 1000000000:
        raise Invalid()
    for k in ("max_streams_bidi", "max_streams_uni"):
        v = cfg[k]
        if not _is_int(v) or v < 0 or v > 1024:
            raise Invalid()
    v = cfg["max_stream_data"]
    if not _is_int(v) or v < 0 or v > 65536:
        raise Invalid()
    v = cfg["max_data"]
    if not _is_int(v) or v < 0 or v > MAXN:
        raise Invalid()
    v = cfg["crypto_limit"]
    if not _is_int(v) or v < 0 or v > 65536:
        raise Invalid()
    sent = cfg["sent"]
    if type(sent) is not dict:
        raise Invalid()
    if set(sent) != frozenset(("I", "H", "A")):
        raise Invalid()
    for k in ("I", "H", "A"):
        _check_ranges_strict(sent[k])


def _validate(doc):
    if type(doc) is not dict:
        raise Invalid()
    if set(doc) != frozenset(("version", "traces")):
        raise Invalid()
    v = doc["version"]
    if not _is_int(v) or v != 1:
        raise Invalid()
    traces = doc["traces"]
    if type(traces) is not list:
        raise Invalid()
    if len(traces) > MAX_TRACES:
        raise Invalid()
    n_events = 0
    n_packets = 0
    n_frames = 0
    n_data = 0
    seen_ids = set()
    for tr in traces:
        if type(tr) is not dict:
            raise Invalid()
        if set(tr) != frozenset(("id", "config", "events")):
            raise Invalid()
        tid = tr["id"]
        if type(tid) is not str or _ID_RE.fullmatch(tid) is None:
            raise Invalid()
        if tid in seen_ids:
            raise Invalid()
        seen_ids.add(tid)
        _validate_config(tr["config"])
        events = tr["events"]
        if type(events) is not list:
            raise Invalid()
        n_events += len(events)
        if n_events > MAX_EVENTS:
            raise Invalid()
        prev_t = None
        for ev in events:
            if type(ev) is not dict:
                raise Invalid()
            ks = set(ev)
            if "t" not in ks or "op" not in ks:
                raise Invalid()
            t = ev["t"]
            if not _is_int(t) or t < 0 or t > 1000000000000:
                raise Invalid()
            if prev_t is not None and t < prev_t:
                raise Invalid()
            prev_t = t
            op = ev["op"]
            if op == "tick":
                if ks != frozenset(("t", "op")):
                    raise Invalid()
            elif op == "key":
                if ks != frozenset(("t", "op", "level", "action")):
                    raise Invalid()
                if ev["level"] not in ("I", "H", "Z", "A"):
                    raise Invalid()
                if ev["action"] not in ("install", "discard"):
                    raise Invalid()
            elif op == "datagram":
                if ks != frozenset(("t", "op", "bytes", "packets")):
                    raise Invalid()
                size = ev["bytes"]
                if not _is_int(size) or size < 0 or size > 65535:
                    raise Invalid()
                pkts = ev["packets"]
                if type(pkts) is not list:
                    raise Invalid()
                npk = len(pkts)
                if npk < 1 or npk > 16:
                    raise Invalid()
                n_packets += npk
                if n_packets > MAX_PACKETS:
                    raise Invalid()
                for p in pkts:
                    if type(p) is not dict:
                        raise Invalid()
                    if set(p) != frozenset(("level", "pn", "auth", "frames")):
                        raise Invalid()
                    if p["level"] not in ("I", "H", "Z", "A"):
                        raise Invalid()
                    pn = p["pn"]
                    if not _is_int(pn) or pn < 0 or pn > MAXN:
                        raise Invalid()
                    if not _is_bool(p["auth"]):
                        raise Invalid()
                    frames = p["frames"]
                    if type(frames) is not list or len(frames) > 64:
                        raise Invalid()
